// Tailwind for NativeWind, themed entirely from the design tokens.
//
// `nativewind-theme.js` is generated by `pnpm --filter @dthcms/design-tokens build` from
// the same JSON source that produces the web CSS variables and the print stylesheet.
// Nothing in this file names a colour or a size, so the mobile app cannot drift from the
// other two surfaces: CP09's build test asserts all three artefacts carry the same
// values.
const { theme } = require('@dthcms/design-tokens/nativewind');

module.exports = {
  content: ['./src/**/*.{ts,tsx}'],
  presets: [require('nativewind/preset')],
  theme,
};
